def is_2_5_smooth(k):
    """Checks if k is of the form 2^a * 5^b."""
    if k <= 0:
        return False
    while k % 2 == 0:
        k //= 2
    while k % 5 == 0:
        k //= 5
    return k == 1

solutions_x = []
# Search up to x = 1000 as a reasonable computational bound.
# Since the task suggests solutions are rare/bounded, this should be adequate.
for x in range(1, 1001, 2):
    k = x**2 + 1
    if is_2_5_smooth(k):
        solutions_x.append(x)

print("Odd integers x such that x^2 + 1 = 2^a 5^b:")
for x in solutions_x:
    print(x)

# Calculate corresponding n = x - 1
solutions_n = [x - 1 for x in solutions_x]
